const lockCard = `-- name: LockCard :one
SELECT id FROM credit_cards WHERE household_id = $1 AND id = $2 FOR UPDATE
`

type LockCardParams struct {
	HouseholdID uuid.UUID
	ID          uuid.UUID
}

// Locks the card row: serialises edits and archiving (and, from F4.3, purchases).
func (q *Queries) LockCard(ctx context.Context, arg LockCardParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockCard, arg.HouseholdID, arg.ID)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const lockCardForPurchase = `-- name: LockCardForPurchase :one
SELECT closing_day, due_day, is_active
FROM credit_cards
WHERE household_id = $1 AND id = $2
FOR UPDATE
`

type LockCardForPurchaseParams struct {
	HouseholdID uuid.UUID
	ID          uuid.UUID
}

type LockCardForPurchaseRow struct {
	ClosingDay int16
	DueDay     int16
	IsActive   bool
}

// Locks the card for a purchase (ADR 0007): serialises the find-or-create of its invoices.
func (q *Queries) LockCardForPurchase(ctx context.Context, arg LockCardForPurchaseParams) (LockCardForPurchaseRow, error) {
	row := q.db.QueryRow(ctx, lockCardForPurchase, arg.HouseholdID, arg.ID)
	var i LockCardForPurchaseRow
	err := row.Scan(&i.ClosingDay, &i.DueDay, &i.IsActive)
	return i, err
}

const lockInvoice = `-- name: LockInvoice :one
SELECT id, credit_card_id, status, closing_on, due_on
FROM card_invoices
WHERE household_id = $1 AND id = $2
FOR UPDATE
`

type LockInvoiceParams struct {
	HouseholdID uuid.UUID
	ID          uuid.UUID
}

type LockInvoiceRow struct {
	ID           uuid.UUID
	CreditCardID uuid.UUID
	Status       string
	ClosingOn    time.Time
	DueOn        time.Time
}

// Locks the invoice (ADR 0007) to close it, pay it or adjust it; purchases lock it too before
// placing installments, so its total never changes under one of these operations.
func (q *Queries) LockInvoice(ctx context.Context, arg LockInvoiceParams) (LockInvoiceRow, error) {
	row := q.db.QueryRow(ctx, lockInvoice, arg.HouseholdID, arg.ID)
	var i LockInvoiceRow
	err := row.Scan(
		&i.ID,
		&i.CreditCardID,
		&i.Status,
		&i.ClosingOn,
		&i.DueOn,
	)
	return i, err
}

const lockOpenInvoices = `-- name: LockOpenInvoices :exec
SELECT id
FROM card_invoices
WHERE household_id = $1 AND credit_card_id = $2 AND status = 'OPEN'
ORDER BY cycle_start_on
FOR UPDATE
`

type LockOpenInvoicesParams struct {
	HouseholdID  uuid.UUID
	CreditCardID uuid.UUID
}

// Locks the card's OPEN invoices (oldest first) so none of them is closed while a purchase
// places installments on it. An invoice closed meanwhile is re-checked and left out.
func (q *Queries) LockOpenInvoices(ctx context.Context, arg LockOpenInvoicesParams) error {
	_, err := q.db.Exec(ctx, lockOpenInvoices, arg.HouseholdID, arg.CreditCardID)
	return err
}

const lockPurchaseInvoices = `-- name: LockPurchaseInvoices :exec
SELECT v.id
FROM card_invoices v
WHERE v.household_id = $1
  AND v.id IN (SELECT i.card_invoice_id FROM card_installments i
               WHERE i.household_id = $1 AND i.transaction_id = $2)
ORDER BY v.cycle_start_on
FOR UPDATE
`

type LockPurchaseInvoicesParams struct {
	HouseholdID   uuid.UUID
	TransactionID uuid.UUID
}

// Locks the invoices of one purchase (oldest first, as purchases do) before its installments
// are cancelled, so no close, payment or adjustment runs on them meanwhile.
func (q *Queries) LockPurchaseInvoices(ctx context.Context, arg LockPurchaseInvoicesParams) error {
	_, err := q.db.Exec(ctx, lockPurchaseInvoices, arg.HouseholdID, arg.TransactionID)
	return err
}

const shareCard = `-- name: ShareCard :one
SELECT name, is_active FROM credit_cards WHERE household_id = $1 AND id = $2 FOR SHARE
`

type ShareCardParams struct {
	HouseholdID uuid.UUID
	ID          uuid.UUID
}

type ShareCardRow struct {
	Name     string
	IsActive bool
}

// Shares the card lock (adjustments): archiving (FOR UPDATE) waits, so a card is never
// archived while an adjustment adds to its balance.
func (q *Queries) ShareCard(ctx context.Context, arg ShareCardParams) (ShareCardRow, error) {
	row := q.db.QueryRow(ctx, shareCard, arg.HouseholdID, arg.ID)
	var i ShareCardRow
	err := row.Scan(&i.Name, &i.IsActive)
	return i, err
}

const sumActiveInstallments = `-- name: SumActiveInstallments :one
SELECT COALESCE(sum(amount_cents), 0)::bigint
FROM card_installments
WHERE household_id = $1 AND card_invoice_id = $2 AND status = 'ACTIVE'
`

type SumActiveInstallmentsParams struct {
	HouseholdID   uuid.UUID
	CardInvoiceID uuid.UUID
}

func (q *Queries) SumActiveInstallments(ctx context.Context, arg SumActiveInstallmentsParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumActiveInstallments, arg.HouseholdID, arg.CardInvoiceID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const updateCard = `-- name: UpdateCard :exec
UPDATE credit_cards
SET name = $1, holder_member_id = $2, last_four = $3, limit_cents = $4,
    closing_day = $5, due_day = $6, is_active = $7, updated_at = now()
WHERE household_id = $8 AND id = $9
`

type UpdateCardParams struct {
	Name           string
	HolderMemberID uuid.UUID
	LastFour       *string
	LimitCents     int64
	ClosingDay     int16
	DueDay         int16
	IsActive       bool
	HouseholdID    uuid.UUID
	ID             uuid.UUID
}

func (q *Queries) UpdateCard(ctx context.Context, arg UpdateCardParams) error {
	_, err := q.db.Exec(ctx, updateCard,
		arg.Name,
		arg.HolderMemberID,
		arg.LastFour,
		arg.LimitCents,
		arg.ClosingDay,
		arg.DueDay,
		arg.IsActive,
		arg.HouseholdID,
		arg.ID,
	)
	return err
}
